"use client"

import Link from "next/link"
import { useState, useEffect, useMemo, useRef, useCallback } from "react"
import { Button } from "@/components/ui/button"
import { AdminAuth } from "@/components/admin-auth"
import { PostCard } from "@/components/post-card"
import { PostEditor } from "@/components/post-editor"
import { Archive, Plus, Filter, Sparkles } from "lucide-react"
import {
  ARCHIVE_ALL_CATEGORY,
  ARCHIVE_CATEGORIES,
  detectArchiveCategory,
  getArchiveCategoryPath,
  normalizeArchiveCategory,
  type ArchiveCategory,
  type ArchiveFilterCategory,
} from "@/lib/archive-categories"

interface Post {
  id: string
  title: string
  content: string
  createdAt: string
  updatedAt?: string
  category?: ArchiveCategory
  customCategory?: string
}

interface SearchArchiveViewProps {
  initialCategory?: ArchiveFilterCategory
}

const LEGACY_STORAGE_KEY = "search_archive_posts"
const LEGACY_CUSTOM_CATEGORY_STORAGE_KEY = "search_archive_custom_categories"
const CUSTOM_CATEGORY_FILTER_ALL = "__all__"
const CUSTOM_CATEGORY_FILTER_UNASSIGNED = "__unassigned__"

type CustomCategoryFilter =
  | typeof CUSTOM_CATEGORY_FILTER_ALL
  | typeof CUSTOM_CATEGORY_FILTER_UNASSIGNED
  | string
type AuthSuccessAction = "new" | "edit" | null

function normalizeCustomCategoryName(input?: string | null): string | undefined {
  if (typeof input !== "string") {
    return undefined
  }

  const normalized = input.replace(/\s+/g, " ").trim()
  return normalized ? normalized : undefined
}

function dedupeCustomCategories(categories: readonly string[]): string[] {
  const uniqueKeys = new Set<string>()
  const result: string[] = []

  for (const category of categories) {
    const normalized = normalizeCustomCategoryName(category)
    if (!normalized) {
      continue
    }

    const key = normalized.toLowerCase()
    if (uniqueKeys.has(key)) {
      continue
    }

    uniqueKeys.add(key)
    result.push(normalized)
  }

  return result
}

function getCustomCategoryMatch(categories: readonly string[], value: string): string | undefined {
  const normalizedValue = value.toLowerCase()
  return categories.find((category) => category.toLowerCase() === normalizedValue)
}

function normalizeAndOrganizePost(
  post: Post,
  touchedAt: string
): { post: Post; changed: boolean } {
  const organizedContent = post.content
  const organizedTitle = post.title.trim() || "검색 정보"
  const detectedCategory = detectArchiveCategory(`${organizedTitle}\n${organizedContent}`)
  const normalizedCategory = normalizeArchiveCategory(detectedCategory)
  const normalizedCustomCategory = normalizeCustomCategoryName(post.customCategory)

  const changed =
    post.title !== organizedTitle ||
    post.content !== organizedContent ||
    post.category !== normalizedCategory ||
    post.customCategory !== normalizedCustomCategory

  return {
    changed,
    post: {
      ...post,
      title: organizedTitle,
      content: organizedContent,
      category: normalizedCategory,
      customCategory: normalizedCustomCategory,
      updatedAt: changed ? post.updatedAt || touchedAt : post.updatedAt,
    },
  }
}

interface ArchiveApiPayload {
  version: number
  posts: Post[]
  customCategories: string[]
}

function mergeArchiveData(
  serverData: ArchiveApiPayload,
  localPosts: Post[],
  localCategories: string[]
) {
  const mergedById = new Map<string, Post>()

  for (const post of serverData.posts) {
    mergedById.set(post.id, post)
  }

  for (const post of localPosts) {
    mergedById.set(post.id, post)
  }

  const mergedPosts = Array.from(mergedById.values())
  const mergedCustomCategories = dedupeCustomCategories([
    ...serverData.customCategories,
    ...localCategories,
    ...mergedPosts
      .map((post) => normalizeCustomCategoryName(post.customCategory))
      .filter((category): category is string => Boolean(category)),
  ])

  return {
    posts: mergedPosts,
    customCategories: mergedCustomCategories,
  }
}

export function SearchArchiveView({
  initialCategory = ARCHIVE_ALL_CATEGORY,
}: SearchArchiveViewProps) {
  const selectedCategory = initialCategory
  const [posts, setPosts] = useState<Post[]>([])
  const [showAuth, setShowAuth] = useState(false)
  const [showEditor, setShowEditor] = useState(false)
  const [editingPost, setEditingPost] = useState<Post | null>(null)
  const [isAuthenticated, setIsAuthenticated] = useState(false)
  const [authSuccessAction, setAuthSuccessAction] = useState<AuthSuccessAction>(null)
  const [customCategories, setCustomCategories] = useState<string[]>([])
  const [selectedCustomCategory, setSelectedCustomCategory] = useState<CustomCategoryFilter>(
    CUSTOM_CATEGORY_FILTER_ALL
  )
  const postsRef = useRef<Post[]>([])
  const customCategoriesRef = useRef<string[]>([])
  const archiveVersionRef = useRef(0)
  const [editorCategory, setEditorCategory] = useState<ArchiveCategory>(
    selectedCategory === ARCHIVE_ALL_CATEGORY ? ARCHIVE_CATEGORIES[0] : selectedCategory
  )

  useEffect(() => {
    postsRef.current = posts
  }, [posts])

  useEffect(() => {
    customCategoriesRef.current = customCategories
  }, [customCategories])

  useEffect(() => {
    setEditorCategory(
      selectedCategory === ARCHIVE_ALL_CATEGORY ? ARCHIVE_CATEGORIES[0] : selectedCategory
    )
  }, [selectedCategory])

  useEffect(() => {
    if (
      selectedCustomCategory !== CUSTOM_CATEGORY_FILTER_ALL &&
      selectedCustomCategory !== CUSTOM_CATEGORY_FILTER_UNASSIGNED &&
      !customCategories.includes(selectedCustomCategory)
    ) {
      setSelectedCustomCategory(CUSTOM_CATEGORY_FILTER_ALL)
    }
  }, [customCategories, selectedCustomCategory])

  const persistArchiveData = useCallback(async (newPosts: Post[], newCategories: string[]) => {
    const response = await fetch("/api/archive", {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        version: archiveVersionRef.current,
        posts: newPosts,
        customCategories: newCategories,
      }),
    })

    if (response.ok) {
      const saved = (await response.json()) as ArchiveApiPayload
      archiveVersionRef.current = saved.version
      return saved
    }

    if (response.status === 409) {
      const conflictResponse = (await response.json()) as { data?: ArchiveApiPayload }
      const latest = conflictResponse.data

      if (!latest) {
        throw new Error("아카이브 충돌 해결에 실패했습니다.")
      }

      const merged = mergeArchiveData(latest, newPosts, newCategories)
      const retryResponse = await fetch("/api/archive", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          version: latest.version,
          posts: merged.posts,
          customCategories: merged.customCategories,
        }),
      })

      if (!retryResponse.ok) {
        throw new Error("아카이브 충돌 해결 재시도에 실패했습니다.")
      }

      const retried = (await retryResponse.json()) as ArchiveApiPayload
      archiveVersionRef.current = retried.version
      return retried
    }

    if (response.status === 401) {
      throw new Error("인증이 만료되었습니다. 다시 인증해주세요.")
    }

    throw new Error("아카이브 저장에 실패했습니다.")
  }, [])

  useEffect(() => {
    let isCancelled = false

    const loadArchiveData = async () => {
      try {
        const response = await fetch("/api/archive", {
          method: "GET",
          cache: "no-store",
        })

        if (!response.ok) {
          throw new Error("아카이브 불러오기에 실패했습니다.")
        }

        const serverData = (await response.json()) as ArchiveApiPayload
        const touchedAt = new Date().toISOString()
        const serverNormalizedResults = (Array.isArray(serverData.posts) ? serverData.posts : []).map(
          (post) => normalizeAndOrganizePost(post, touchedAt)
        )
        const serverNormalizedPosts = serverNormalizedResults.map((result) => result.post)
        const serverCustomCategories = dedupeCustomCategories(
          Array.isArray(serverData.customCategories)
            ? serverData.customCategories.filter((item): item is string => typeof item === "string")
            : []
        )
        archiveVersionRef.current =
          typeof serverData.version === "number" && Number.isFinite(serverData.version)
            ? Math.floor(serverData.version)
            : 0

        let mergedPosts = serverNormalizedPosts
        let mergedCustomCategories = serverCustomCategories
        let shouldSyncServer = serverNormalizedResults.some((result) => result.changed)

        const legacyPostsRaw = localStorage.getItem(LEGACY_STORAGE_KEY)
        const legacyCustomCategoriesRaw = localStorage.getItem(LEGACY_CUSTOM_CATEGORY_STORAGE_KEY)

        if (legacyPostsRaw || legacyCustomCategoriesRaw) {
          let legacyPosts: Post[] = []
          let legacyCustomCategories: string[] = []

          if (legacyPostsRaw) {
            try {
              const parsed = JSON.parse(legacyPostsRaw)
              if (Array.isArray(parsed)) {
                legacyPosts = parsed
                  .filter((item): item is Post => Boolean(item && typeof item === "object"))
                  .map((post) => normalizeAndOrganizePost(post, touchedAt).post)
              }
            } catch {
              legacyPosts = []
            }
          }

          if (legacyCustomCategoriesRaw) {
            try {
              const parsed = JSON.parse(legacyCustomCategoriesRaw)
              if (Array.isArray(parsed)) {
                legacyCustomCategories = dedupeCustomCategories(
                  parsed.filter((item): item is string => typeof item === "string")
                )
              }
            } catch {
              legacyCustomCategories = []
            }
          }

          if (legacyPosts.length > 0 || legacyCustomCategories.length > 0) {
            const byId = new Map<string, Post>()

            for (const post of [...legacyPosts, ...serverNormalizedPosts]) {
              byId.set(post.id, post)
            }

            mergedPosts = Array.from(byId.values())
            mergedCustomCategories = dedupeCustomCategories([
              ...serverCustomCategories,
              ...legacyCustomCategories,
              ...mergedPosts
                .map((post) => normalizeCustomCategoryName(post.customCategory))
                .filter((category): category is string => Boolean(category)),
            ])

            shouldSyncServer = true
          }
        }

        if (isCancelled) {
          return
        }

        setPosts(mergedPosts)
        setCustomCategories(mergedCustomCategories)

        if (shouldSyncServer) {
          try {
            const saved = await persistArchiveData(mergedPosts, mergedCustomCategories)
            if (!isCancelled) {
              setPosts(saved.posts)
              setCustomCategories(saved.customCategories)
            }
            localStorage.removeItem(LEGACY_STORAGE_KEY)
            localStorage.removeItem(LEGACY_CUSTOM_CATEGORY_STORAGE_KEY)
          } catch {
            // Keep legacy data for retry when sync fails.
          }
        }
      } catch {
        if (!isCancelled) {
          setPosts([])
          setCustomCategories([])
        }
      }
    }

    void loadArchiveData()

    return () => {
      isCancelled = true
    }
  }, [persistArchiveData])

  const savePosts = useCallback(
    (newPosts: Post[]) => {
      setPosts(newPosts)
      postsRef.current = newPosts

      void persistArchiveData(newPosts, customCategoriesRef.current)
        .then((saved) => {
          setPosts(saved.posts)
          setCustomCategories(saved.customCategories)
          postsRef.current = saved.posts
          customCategoriesRef.current = saved.customCategories
        })
        .catch((error: unknown) => {
          if (error instanceof Error && error.message.includes("인증이 만료")) {
            setIsAuthenticated(false)
            setShowAuth(true)
            return
          }

          alert("아카이브 저장에 실패했습니다. 잠시 후 다시 시도해주세요.")
        })
    },
    [persistArchiveData]
  )

  const saveCustomCategories = useCallback(
    (newCategories: string[]) => {
      setCustomCategories(newCategories)
      customCategoriesRef.current = newCategories

      void persistArchiveData(postsRef.current, newCategories)
        .then((saved) => {
          setPosts(saved.posts)
          setCustomCategories(saved.customCategories)
          postsRef.current = saved.posts
          customCategoriesRef.current = saved.customCategories
        })
        .catch((error: unknown) => {
          if (error instanceof Error && error.message.includes("인증이 만료")) {
            setIsAuthenticated(false)
            setShowAuth(true)
            return
          }

          alert("아카이브 저장에 실패했습니다. 잠시 후 다시 시도해주세요.")
        })
    },
    [persistArchiveData]
  )

  const handleOrganizeAllPosts = () => {
    if (posts.length === 0) {
      return
    }

    const touchedAt = new Date().toISOString()
    const reorganizedResults = posts.map((post) => normalizeAndOrganizePost(post, touchedAt))
    const changedCount = reorganizedResults.filter((result) => result.changed).length

    if (changedCount === 0) {
      alert("이미 최신 카테고리 기준으로 분류되어 있습니다.")
      return
    }

    const nextPosts = reorganizedResults.map((result) => result.post)
    savePosts(nextPosts)
    alert(`${changedCount}개의 정리글 카테고리를 다시 분류했습니다.`)
  }

  const handleNewPost = () => {
    if (!isAuthenticated) {
      setAuthSuccessAction("new")
      setShowAuth(true)
      return
    }

    setEditingPost(null)
    setAuthSuccessAction(null)
    setEditorCategory(
      selectedCategory === ARCHIVE_ALL_CATEGORY ? ARCHIVE_CATEGORIES[0] : selectedCategory
    )
    setShowEditor(true)
  }

  const handleAuthenticated = () => {
    const action = authSuccessAction

    setIsAuthenticated(true)
    setShowAuth(false)

    if (action === "new") {
      setEditingPost(null)
      setEditorCategory(
        selectedCategory === ARCHIVE_ALL_CATEGORY ? ARCHIVE_CATEGORIES[0] : selectedCategory
      )
      setShowEditor(true)
    }

    if (action === "edit" && editingPost) {
      setShowEditor(true)
    }

    setAuthSuccessAction(null)
  }

  const handleSavePost = (title: string, content: string, categoryInput?: string) => {
    const organizedContent = content
    const organizedTitle = title
    const category = normalizeArchiveCategory(
      categoryInput || detectArchiveCategory(`${organizedTitle}\n${organizedContent}`)
    )

    if (editingPost) {
      const updatedPosts = posts.map((post) =>
        post.id === editingPost.id
          ? {
              ...post,
              title: organizedTitle,
              content: organizedContent,
              category,
              updatedAt: new Date().toISOString(),
            }
          : post
      )
      savePosts(updatedPosts)
    } else {
      const selectedCustomCategoryName =
        selectedCustomCategory !== CUSTOM_CATEGORY_FILTER_ALL &&
        selectedCustomCategory !== CUSTOM_CATEGORY_FILTER_UNASSIGNED
          ? selectedCustomCategory
          : undefined

      const newCustomCategory = selectedCustomCategoryName
        ? getCustomCategoryMatch(customCategories, selectedCustomCategoryName) ||
          selectedCustomCategoryName
        : undefined

      const newPost: Post = {
        id: Date.now().toString(),
        title: organizedTitle,
        content: organizedContent,
        category,
        customCategory: newCustomCategory,
        createdAt: new Date().toISOString(),
      }
      savePosts([newPost, ...posts])

      if (newCustomCategory && !getCustomCategoryMatch(customCategories, newCustomCategory)) {
        saveCustomCategories([...customCategories, newCustomCategory])
      }
    }

    setShowEditor(false)
    setEditingPost(null)
  }

  const handleEditPost = (post: Post) => {
    const normalizedPost = {
      ...post,
      category: normalizeArchiveCategory(post.category),
    }

    if (!isAuthenticated) {
      setEditingPost(normalizedPost)
      setEditorCategory(normalizedPost.category)
      setAuthSuccessAction("edit")
      setShowAuth(true)
      return
    }

    setEditingPost(normalizedPost)
    setEditorCategory(normalizedPost.category)
    setAuthSuccessAction(null)
    setShowEditor(true)
  }

  const handleDeletePost = (postId: string) => {
    if (!isAuthenticated) {
      setAuthSuccessAction(null)
      setShowAuth(true)
      return
    }

    if (confirm("정말 이 정리글을 삭제하시겠습니까?")) {
      const newPosts = posts.filter((post) => post.id !== postId)
      savePosts(newPosts)
    }
  }

  const handleCreateCustomCategory = () => {
    if (!isAuthenticated) {
      setAuthSuccessAction(null)
      setShowAuth(true)
      return
    }

    const input = prompt("새 압축 카테고리 이름을 입력하세요.")
    if (input === null) {
      return
    }

    const normalizedCategory = normalizeCustomCategoryName(input)
    if (!normalizedCategory) {
      alert("카테고리 이름을 입력해주세요.")
      return
    }

    const existingCategory = getCustomCategoryMatch(customCategories, normalizedCategory)
    if (existingCategory) {
      setSelectedCustomCategory(existingCategory)
      alert("이미 존재하는 압축 카테고리입니다.")
      return
    }

    const nextCategories = [...customCategories, normalizedCategory]
    saveCustomCategories(nextCategories)
    setSelectedCustomCategory(normalizedCategory)
  }

  const handleAssignCustomCategory = (targetPost: Post) => {
    if (!isAuthenticated) {
      setAuthSuccessAction(null)
      setShowAuth(true)
      return
    }

    const existingCategoriesHint = customCategories.length
      ? `\n기존 카테고리: ${customCategories.join(", ")}`
      : ""

    const input = prompt(
      `압축 카테고리 이름을 입력하세요.\n비워두면 압축 분류가 해제됩니다.${existingCategoriesHint}`,
      targetPost.customCategory || ""
    )

    if (input === null) {
      return
    }

    const normalizedInput = normalizeCustomCategoryName(input)
    const resolvedCustomCategory = normalizedInput
      ? getCustomCategoryMatch(customCategories, normalizedInput) || normalizedInput
      : undefined

    const updatedPosts = posts.map((post) =>
      post.id === targetPost.id
        ? {
            ...post,
            customCategory: resolvedCustomCategory,
            updatedAt: new Date().toISOString(),
          }
        : post
    )

    savePosts(updatedPosts)

    if (
      resolvedCustomCategory &&
      !getCustomCategoryMatch(customCategories, resolvedCustomCategory)
    ) {
      saveCustomCategories([...customCategories, resolvedCustomCategory])
    }

    if (resolvedCustomCategory) {
      setSelectedCustomCategory(resolvedCustomCategory)
    }
  }

  const categoryCounts = useMemo(() => {
    const counts = Object.fromEntries(ARCHIVE_CATEGORIES.map((category) => [category, 0])) as Record<
      ArchiveCategory,
      number
    >

    for (const post of posts) {
      const category = normalizeArchiveCategory(post.category)
      counts[category] += 1
    }

    return counts
  }, [posts])

  const customCategoryCounts = useMemo(() => {
    const counts: Record<string, number> = {}
    let uncategorizedCount = 0

    for (const post of posts) {
      const customCategory = normalizeCustomCategoryName(post.customCategory)

      if (!customCategory) {
        uncategorizedCount += 1
        continue
      }

      counts[customCategory] = (counts[customCategory] || 0) + 1
    }

    return {
      counts,
      uncategorizedCount,
    }
  }, [posts])

  const filteredPosts = useMemo(() => {
    const categoryFilteredPosts =
      selectedCategory === ARCHIVE_ALL_CATEGORY
        ? posts
        : posts.filter((post) => normalizeArchiveCategory(post.category) === selectedCategory)

    if (selectedCustomCategory === CUSTOM_CATEGORY_FILTER_ALL) {
      return categoryFilteredPosts
    }

    if (selectedCustomCategory === CUSTOM_CATEGORY_FILTER_UNASSIGNED) {
      return categoryFilteredPosts.filter((post) => !normalizeCustomCategoryName(post.customCategory))
    }

    return categoryFilteredPosts.filter(
      (post) => normalizeCustomCategoryName(post.customCategory) === selectedCustomCategory
    )
  }, [posts, selectedCategory, selectedCustomCategory])

  const sortedFilteredPosts = useMemo(() => {
    return [...filteredPosts].sort((a, b) => {
      const aTime = new Date(a.updatedAt || a.createdAt).getTime()
      const bTime = new Date(b.updatedAt || b.createdAt).getTime()
      return bTime - aTime
    })
  }, [filteredPosts])

  const groupedPostsByCategory = useMemo(() => {
    const grouped = Object.fromEntries(
      ARCHIVE_CATEGORIES.map((category) => [category, [] as Post[]])
    ) as Record<ArchiveCategory, Post[]>

    for (const post of sortedFilteredPosts) {
      const category = normalizeArchiveCategory(post.category)
      grouped[category].push(post)
    }

    return ARCHIVE_CATEGORIES.map((category) => ({
      category,
      posts: grouped[category],
    })).filter((group) => group.posts.length > 0)
  }, [sortedFilteredPosts])

  const emptyStateText =
    selectedCustomCategory === CUSTOM_CATEGORY_FILTER_ALL
      ? "선택한 카테고리에 저장된 정보가 없습니다."
      : "선택한 압축 카테고리에 저장된 정보가 없습니다."

  return (
    <div className="min-h-screen p-6 md:p-10">
      <div className="max-w-3xl mx-auto">
        <div className="flex items-center justify-between mb-6 pt-8 md:pt-0">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-secondary rounded-sm">
              <Archive className="h-5 w-5 text-foreground" />
            </div>
            <div>
              <h1 className="text-2xl md:text-3xl font-bold text-foreground">검색 정리함</h1>
              <p className="text-muted-foreground text-sm">
                정보검색엔진 결과를 카테고리로 정리하고 저장하는 공간
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Button
              type="button"
              variant="outline"
              onClick={handleOrganizeAllPosts}
              disabled={posts.length === 0}
              className="gap-2"
            >
              <Sparkles className="h-4 w-4" />
              <span className="hidden sm:inline">카테고리 재분류</span>
            </Button>
            <Button onClick={handleNewPost} className="gap-2">
              <Plus className="h-4 w-4" />
              <span className="hidden sm:inline">새 정리 작성</span>
            </Button>
          </div>
        </div>

        {posts.length > 0 ? (
          <section className="mb-8 border border-border rounded-sm bg-card p-4">
            <div className="flex items-center gap-2 text-sm text-muted-foreground mb-3">
              <Filter className="h-4 w-4" />
              카테고리별 보기
            </div>
            <div className="flex flex-wrap gap-2">
              <Button asChild type="button" size="sm" variant={selectedCategory === ARCHIVE_ALL_CATEGORY ? "default" : "outline"}>
                <Link href="/search-archive">전체 ({posts.length})</Link>
              </Button>
              {ARCHIVE_CATEGORIES.map((category) => (
                <Button
                  asChild
                  key={category}
                  type="button"
                  size="sm"
                  variant={selectedCategory === category ? "default" : "outline"}
                >
                  <Link href={getArchiveCategoryPath(category)}>
                    {category} ({categoryCounts[category]})
                  </Link>
                </Button>
              ))}
            </div>

            <div className="mt-5 border-t border-border/60 pt-4">
              <div className="mb-3 flex items-center justify-between gap-2">
                <div className="flex items-center gap-2 text-sm text-muted-foreground">
                  <Archive className="h-4 w-4" />
                  압축 카테고리
                </div>
                <Button
                  type="button"
                  size="sm"
                  variant="outline"
                  className="gap-1.5"
                  onClick={handleCreateCustomCategory}
                >
                  <Plus className="h-3.5 w-3.5" />
                  카테고리 만들기
                </Button>
              </div>
              <div className="flex flex-wrap gap-2">
                <Button
                  type="button"
                  size="sm"
                  variant={
                    selectedCustomCategory === CUSTOM_CATEGORY_FILTER_ALL ? "default" : "outline"
                  }
                  onClick={() => setSelectedCustomCategory(CUSTOM_CATEGORY_FILTER_ALL)}
                >
                  전체 ({posts.length})
                </Button>
                <Button
                  type="button"
                  size="sm"
                  variant={
                    selectedCustomCategory === CUSTOM_CATEGORY_FILTER_UNASSIGNED
                      ? "default"
                      : "outline"
                  }
                  onClick={() => setSelectedCustomCategory(CUSTOM_CATEGORY_FILTER_UNASSIGNED)}
                >
                  미분류 ({customCategoryCounts.uncategorizedCount})
                </Button>
                {customCategories.map((customCategory) => (
                  <Button
                    key={customCategory}
                    type="button"
                    size="sm"
                    variant={selectedCustomCategory === customCategory ? "default" : "outline"}
                    onClick={() => setSelectedCustomCategory(customCategory)}
                  >
                    {customCategory} ({customCategoryCounts.counts[customCategory] || 0})
                  </Button>
                ))}
              </div>
              <p className="mt-3 text-xs text-muted-foreground">
                각 정리글의 "압축 카테고리 지정" 버튼으로 원하는 카테고리에 넣을 수 있습니다.
              </p>
            </div>
          </section>
        ) : null}

        <div className="space-y-6">
          {posts.length === 0 ? (
            <div className="text-center py-20 text-muted-foreground border border-border rounded-sm bg-card">
              <p>아직 저장된 검색 결과가 없습니다.</p>
              <p className="text-sm mt-2">
                정보검색엔진 답변 아래 "정리함에 저장" 버튼을 눌러 보관하세요.
              </p>
              <Button asChild variant="outline" className="mt-6">
                <Link href="/search-engine">정보검색엔진으로 이동</Link>
              </Button>
            </div>
          ) : sortedFilteredPosts.length === 0 ? (
            <div className="text-center py-20 text-muted-foreground border border-border rounded-sm bg-card">
              {emptyStateText}
            </div>
          ) : selectedCategory === ARCHIVE_ALL_CATEGORY ? (
            groupedPostsByCategory.map((group) => (
              <section key={group.category} className="space-y-3">
                <header className="flex items-center justify-between border-b border-border/70 pb-2">
                  <h2 className="text-sm font-semibold text-foreground/90">{group.category}</h2>
                  <span className="inline-flex items-center rounded-sm bg-secondary px-2 py-1 text-xs text-foreground/80">
                    {group.posts.length}개
                  </span>
                </header>
                <div className="space-y-4">
                  {group.posts.map((post) => (
                    <PostCard
                      key={post.id}
                      post={{
                        ...post,
                        category: normalizeArchiveCategory(post.category),
                        customCategory: normalizeCustomCategoryName(post.customCategory),
                      }}
                      onEdit={() => handleEditPost(post)}
                      onDelete={() => handleDeletePost(post.id)}
                      onAssignCustomCategory={() => handleAssignCustomCategory(post)}
                      showActions={isAuthenticated}
                    />
                  ))}
                </div>
              </section>
            ))
          ) : (
            sortedFilteredPosts.map((post) => (
              <PostCard
                key={post.id}
                post={{
                  ...post,
                  category: normalizeArchiveCategory(post.category),
                  customCategory: normalizeCustomCategoryName(post.customCategory),
                }}
                onEdit={() => handleEditPost(post)}
                onDelete={() => handleDeletePost(post.id)}
                onAssignCustomCategory={() => handleAssignCustomCategory(post)}
                showActions={isAuthenticated}
              />
            ))
          )}
        </div>
      </div>

      {showAuth && (
        <AdminAuth
          onAuthenticated={handleAuthenticated}
          onCancel={() => {
            setShowAuth(false)
            setEditingPost(null)
            setAuthSuccessAction(null)
          }}
        />
      )}

      {showEditor && (
        <PostEditor
          initialTitle={editingPost?.title || ""}
          initialContent={editingPost?.content || ""}
          initialCategory={editingPost?.category || editorCategory}
          categories={ARCHIVE_CATEGORIES}
          onSave={handleSavePost}
          onCancel={() => {
            setShowEditor(false)
            setEditingPost(null)
          }}
        />
      )}
    </div>
  )
}
